function Find-BootstrapExecutable {
    param([string]$Name,[string[]]$Candidates=@())
    $command=Get-Command $Name -CommandType Application -ErrorAction SilentlyContinue|Select-Object -First 1
    if($command){return $command.Source}
    foreach($candidate in $Candidates){if($candidate -and(Test-Path -LiteralPath $candidate -PathType Leaf)){return $candidate}}
    return $null
}

function ConvertTo-WindowsArgument {
    param([AllowEmptyString()][string]$Value)
    $builder=New-Object Text.StringBuilder
    [void]$builder.Append('"')
    $slashes=0
    foreach($character in $Value.ToCharArray()) {
        if($character -eq '\'){$slashes++;continue}
        if($character -eq '"') {
            [void]$builder.Append(('\' * (2*$slashes+1)))
            [void]$builder.Append('"')
        } else {
            [void]$builder.Append(('\' * $slashes))
            [void]$builder.Append($character)
        }
        $slashes=0
    }
    [void]$builder.Append(('\' * (2*$slashes)))
    [void]$builder.Append('"')
    return $builder.ToString()
}

function Invoke-BootstrapProcess {
    param([string]$FilePath,[string[]]$Arguments,[int]$TimeoutSeconds=1800)
    $start=New-Object Diagnostics.ProcessStartInfo
    $start.FileName=$FilePath
    $quoted=@(foreach($argument in $Arguments){ConvertTo-WindowsArgument $argument})
    $start.Arguments=$quoted -join ' '
    $start.UseShellExecute=$false
    # Native stderr remains native output; a successful installer warning is not a PS failure.
    $process=New-Object Diagnostics.Process
    $process.StartInfo=$start
    $evidenceWatch=[Diagnostics.Stopwatch]::StartNew();$evidenceExit=$null;$evidenceError=$null
    try {
        [void]$process.Start()
        if($TimeoutSeconds -eq 0){$process.WaitForExit()}
        elseif(-not $process.WaitForExit($TimeoutSeconds*1000)){
            $process.Kill()
            throw "Timeout ($TimeoutSeconds s) for $([IO.Path]::GetFileName($FilePath)). Child installers/services may still be running; check their status before retrying."
        }
        $evidenceExit=$process.ExitCode
        return $process.ExitCode
    } catch {$evidenceError=$_.Exception.Message;throw}
    finally {
        $process.Dispose()
        if(Get-Variable bootstrapCommands -Scope Script -ErrorAction SilentlyContinue){$script:bootstrapCommands+=@(@{utc=[DateTime]::UtcNow.ToString('o');file=$FilePath;arguments=$Arguments;timeoutSeconds=$TimeoutSeconds;exitCode=$evidenceExit;durationMs=$evidenceWatch.Elapsed.TotalMilliseconds;error=$evidenceError;consoleOutput='Inherited interactive console; Setup child captures its own detailed evidence.'})}
    }
}

function Read-BootstrapInventory {
    $bytes=Get-BootstrapPayloadBytes
    Add-Type -AssemblyName System.IO.Compression
    $memory=New-Object IO.MemoryStream(,$bytes)
    $archive=New-Object IO.Compression.ZipArchive($memory,[IO.Compression.ZipArchiveMode]::Read,$false)
    $files=@{}
    try{
        foreach($entry in $archive.Entries){
            if($files.ContainsKey($entry.FullName)){throw 'Duplicate entry in the audit package.'}
            $reader=New-Object IO.StreamReader($entry.Open())
            try{$files[$entry.FullName]=$reader.ReadToEnd()}finally{$reader.Dispose()}
        }
    }finally{$archive.Dispose();$memory.Dispose()}
    if(-not $files.ContainsKey('Audit.ps1') -or -not $files.ContainsKey('Runtime.ps1') -or -not $files.ContainsKey('Common.ps1') -or -not $files.ContainsKey('ModelSelection.ps1') -or -not $files.ContainsKey('Ripgrep.ps1')){throw 'Audit module or shared module missing from the embedded package.'}
    & ([scriptblock]::Create($files['Audit.ps1'])) -InstallRoot $InstallRoot -BundleVersion $bundleVersion -PayloadHash $payloadSha256 -PackageFiles $files `
        -ModelMode $ModelMode -IndexingMode $IndexingMode -IncludeFastModel ([bool]$IncludeFastModel) -AllowPartialGpuOffload ([bool]$AllowPartialGpuOffload) -PreferredModel $PreferredModel -ModelKey $ModelKey `
        -ContextLength $ContextLength -Port $Port -RouterPort $RouterPort -ApiTokenEnvironmentVariable $ApiTokenEnvironmentVariable `
        -ProjectPath $ProjectPath -SkipModelDownload ([bool]$SkipModelDownload)
}

function Assert-BootstrapOptions {
    if($ModelMode -ne 'Dual' -and $IndexingMode -ne 'Off'){throw 'Semantic indexing requires ModelMode Dual.'}
    if($ModelMode -ne 'Dual' -and $AllowPartialGpuOffload){throw 'AllowPartialGpuOffload is supported only in the model pool (ModelMode Dual).'}
    if($ModelMode -eq 'Single' -and $IncludeFastModel){throw 'IncludeFastModel requires ModelMode Dual.'}
    if($ModelMode -eq 'Dual' -and ($ModelKey -or $PreferredModel -eq 'GptOss20B')){throw 'A custom model or GptOss20B as a single model requires -ModelMode Single.'}
    if($ModelMode -eq 'Dual' -and $Port -eq $RouterPort){throw 'Backend and router ports must be different.'}
    if($ApiTokenEnvironmentVariable -and $ApiTokenEnvironmentVariable -notmatch '^[A-Za-z_][A-Za-z0-9_]*$'){throw 'Invalid API token environment variable name.'}
    foreach($project in $ProjectPath){if(-not(Test-Path -LiteralPath $project -PathType Container)){throw "Project directory not found: $project"}}
}

function Select-BootstrapModelAction {
    param([string]$Root,[string]$Requested,[hashtable]$Previous,[System.Collections.IDictionary]$Arguments,[switch]$Copying)
    if ($Requested -eq 'Configure') {return @{Action='Configure';IndexingMode='Off'}}
    $canKeep=$false
    $savedIndexing='Off'
    if (!$Copying -and $Previous['ModelMode'] -in @('Single','Dual')) {
        $chainPath=Join-Path $Root 'toolchain.json'
        $filename=if ($Previous.ModelMode -eq 'Dual') {'runtime/model-pool.json'} else {'runtime/runtime-state.json'}
        $statePath=Join-Path $Root $filename
        if ((Test-Path -LiteralPath $chainPath -PathType Leaf) -and (Test-Path -LiteralPath $statePath -PathType Leaf)) {
            Assert-BootstrapNoReparsePoint -Path $chainPath
            Assert-BootstrapNoReparsePoint -Path $statePath
            $chain=Get-Content -LiteralPath $chainPath -Raw | ConvertFrom-Json
            $state=Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json
            $canKeep=$null -ne $chain -and $null -ne $state -and $chain.PSObject.Properties['modelMode'] -and $state.PSObject.Properties['Status'] -and $chain.modelMode -eq $Previous.ModelMode -and ($state.Status -eq 'Ready' -or
                ($chain.modelMode -eq 'Single' -and $state.Status -eq 'Deferred'))
            if ($canKeep -and $chain.PSObject.Properties['indexingMode']) {$savedIndexing=$chain.indexingMode}
        }
    }
    if ($canKeep) {
        foreach ($name in @('ModelMode','IncludeFastModel','AllowPartialGpuOffload','AllowUnfitAttempt','RouterPort','PreferredModel','ModelKey','ApiTokenEnvironmentVariable','ContextLength','Port','IndexingMode')) {
            if (!$Arguments.ContainsKey($name)) {continue}
            $old=if ($name -eq 'IndexingMode') {$savedIndexing} else {$Previous[$name]}
            if ($Arguments[$name] -ne $old) {$canKeep=$false;break}
        }
    }
    if (!$canKeep -and $Requested -eq 'Keep') {throw 'Keep requires an existing runtime with matching model options. Use -ModelAction Configure to initialize or change it.'}
    if (!$Requested) {
        if ($canKeep) {
            $answer=Read-Host 'Models: [Enter/1] keep existing models and skip downloads/loading/tests, [2] select or update models'
            $Requested=switch ($answer.Trim()) {'' {'Keep'} '1' {'Keep'} '2' {'Configure'} default {throw 'Invalid model action. Choose 1 or 2.'}}
        } else {$Requested='Configure'}
    }
    return @{Action=$Requested;IndexingMode=$savedIndexing}
}

function Select-BootstrapIndexingMode {
    param([string]$ResolvedModelMode='Dual')
    if($ResolvedModelMode -ne 'Dual'){return 'Off'}
    Write-Host "`nLOCAL SEMANTIC INDEXING (optional; default Off)"
    Write-Host '0: Off - no embedding download, load or indexing for managed projects.'
    Write-Host '1: OnDemand - prepare components; ask at each desktop launch (default No).'
    Write-Host '2: Automatic - start at launch after the one-time Kilo project consent.'
    Write-Host 'Existing index files and downloaded models are preserved. Close managed VS Code windows before updating.'
    $choice=(Read-Host 'Select 0/1/2; Enter chooses Off').Trim()
    switch($choice){''{return 'Off'} '0'{return 'Off'} '1'{return 'OnDemand'} '2'{return 'Automatic'} default{throw 'Invalid indexing selection. No installation changes performed.'}}
}

function Read-BootstrapOptionState {
    param([string]$Root)
    $known=@('ModelMode','IncludeFastModel','AllowPartialGpuOffload','AllowUnfitAttempt','RouterPort','PreferredModel','ModelKey','ApiTokenEnvironmentVariable','ContextLength','Port')
    $settings=@{}
    if(-not(Test-Path -LiteralPath (Join-Path $Root 'shadow-local-ai-install.json') -PathType Leaf)){return $settings}
    $saved=Join-Path $Root 'provisioning-options.json'
    if(Test-Path -LiteralPath $saved){
        Assert-BootstrapNoReparsePoint -Path $saved
        $document=Get-Content -LiteralPath $saved -Raw | ConvertFrom-Json
        if($document -isnot [pscustomobject]){throw 'Saved provisioning options are invalid.'}
        foreach($property in $document.PSObject.Properties){if($property.Name -in $known){$settings[$property.Name]=$property.Value}}
        return $settings
    }
    # Recover the actual last configuration written by earlier releases.
    $chainPath=Join-Path $Root 'toolchain.json'
    if(-not(Test-Path -LiteralPath $chainPath -PathType Leaf)){return $settings}
    Assert-BootstrapNoReparsePoint -Path $chainPath
    $chain=Get-Content -LiteralPath $chainPath -Raw | ConvertFrom-Json
    if(-not $chain.PSObject.Properties['modelMode'] -or $chain.modelMode -notin @('Single','Dual')){return $settings}
    $settings.ModelMode=$chain.modelMode
    if($chain.PSObject.Properties['allowUnfitAttempt']){$settings.AllowUnfitAttempt=$chain.allowUnfitAttempt}
    if($chain.modelMode -eq 'Dual'){
        $statePath=Join-Path $Root 'runtime/model-pool.json'
        if(Test-Path -LiteralPath $statePath -PathType Leaf){
            Assert-BootstrapNoReparsePoint -Path $statePath
            $state=Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json
            if($state.Status -eq 'Ready'){
                $settings.IncludeFastModel=(@($state.Profiles | Where-Object {$_.Alias -eq 'fast'}).Count -gt 0)
                if($state.PSObject.Properties['AllowPartialGpuOffload']){$settings.AllowPartialGpuOffload=$state.AllowPartialGpuOffload}
                $settings.ContextLength=$state.ContextLength
                $settings.ApiTokenEnvironmentVariable=$state.ApiTokenEnvironmentVariable
                $settings.Port=([uri]$state.BackendApiBaseUrl).Port
                $settings.RouterPort=([uri]$state.RouterApiBaseUrl).Port
            }
        }
    }else{
        $statePath=Join-Path $Root 'runtime/runtime-state.json'
        if(Test-Path -LiteralPath $statePath -PathType Leaf){
            Assert-BootstrapNoReparsePoint -Path $statePath
            $state=Get-Content -LiteralPath $statePath -Raw | ConvertFrom-Json
            if($state.Status -in @('Ready','Deferred')){
                foreach($name in @('ContextLength','Port','ApiTokenEnvironmentVariable')){$settings[$name]=$state.$name}
                if(-not(Test-Path -LiteralPath (Join-Path $Root 'model-selection.json'))){$settings.ModelKey=$state.ModelPath}
            }
        }
    }
    return $settings
}

function Assert-BootstrapInstallRoot {
    param([string]$Root=$InstallRoot,[switch]$AllowSharedDirectory)
    Assert-BootstrapNoReparsePoint -Path (Join-Path $Root 'app')
    Assert-BootstrapNoReparsePoint -Path (Join-Path $Root 'backups\app')
    if((Test-Path -LiteralPath $Root) -and -not(Test-Path -LiteralPath $Root -PathType Container)){throw 'InstallRoot is not a directory.'}
    $marker=Join-Path $Root 'shadow-local-ai-install.json'
    Assert-BootstrapNoReparsePoint -Path $marker
    if(Test-Path -LiteralPath $marker){
        try{$identity=Get-Content -LiteralPath $marker -Raw|ConvertFrom-Json}
        catch{throw 'Package identity is unreadable or invalid JSON. Existing files are preserved.'}
        if($null -eq $identity -or $null -eq $identity.PSObject.Properties['product'] -or
           $null -eq $identity.PSObject.Properties['schema'] -or $identity.product -cne 'ShadowLocalAI' -or $identity.schema -ne 1){
            throw 'InstallRoot contains an unknown package identity. Existing files are preserved.'
        }
    }elseif(Test-Path -LiteralPath $Root){
        $children=@(Get-ChildItem -LiteralPath $Root -Force)
        if(-not $AllowSharedDirectory -and $children.Count -gt 0){
            throw 'InstallRoot is not empty and does not belong to this package. Select a new, empty directory.'
        }
        $reserved=@('app','backups','inventory.json','toolchain.json','provisioning-report.json','provisioning-options.json','update-policy.json','provisioning.lock','setup-active.lock','model-downloads','model-selection.json',
            'runtime','runtime-profile','tooling','kilo-managed','vscode-data','vscode-extensions','welcome',
            'workspaces','workspaces.json','projects','runs')
        foreach($child in $children){
            if($child.Name -in $reserved -or $child.Name -like 'setup-request-*.json' -or $child.Name -like '.shadow-copy-*'){
                throw "Name conflict without a package identity: $($child.FullName). Existing files are preserved; choose another destination with -InstallRoot."
            }
        }
    }
}

function Select-BootstrapInstallation {
    param([string]$RequestedRoot,[string]$LegacyRoot)
    $target=[IO.Path]::GetFullPath($RequestedRoot)
    if($target -ne [IO.Path]::GetPathRoot($target)){$target=$target.TrimEnd('\','/')}
    $legacy=[IO.Path]::GetFullPath($LegacyRoot).TrimEnd('\','/')
    $source=$null
    if($target -ine $legacy -and (Test-Path -LiteralPath $legacy)){
        Write-Host "Previous installation directory found: $legacy"
        $marker=Join-Path $target 'shadow-local-ai-install.json'
        $targetOwned=$false
        $targetInvalid=$false
        if(Test-Path -LiteralPath $marker){
            try{
                Assert-BootstrapInstallRoot -Root $target -AllowSharedDirectory
                $targetOwned=$true
            }catch{
                $targetInvalid=$true
                Write-Host "Cannot verify the package identity at the destination: $($_.Exception.Message)"
            }
        }
        if($targetOwned){
            Write-Host "A valid LoKiEnte package identity was found at the destination: $target"
            Write-Host 'This confirms neither a complete copy nor completed provisioning.'
            Write-Host 'To continue setup at the destination, select option 1; nothing is merged automatically.'
        }
        Write-Host "1: Use destination: $target (continue an existing installation there or create a new one)"
        Write-Host "2: Reuse previous directory: $legacy"
        Write-Host "3: Copy the existing installation to $target and continue there (no merging)"
        while($true){
            $choice=Read-Host 'Select 1/2/3; any other input cancels'
            switch($choice){
                '1' {return [pscustomobject]@{Root=$target;CopyFrom=$null}}
                '2' {return [pscustomobject]@{Root=$legacy;CopyFrom=$null}}
                '3' {
                    if($targetOwned -or $targetInvalid){
                        Write-Host 'Cannot copy again: the destination already contains a package identity. No files were changed. Select option 1 or 2; no merging is performed.'
                        continue
                    }
                    Assert-BootstrapInstallRoot -Root $legacy
                    if(-not(Test-Path -LiteralPath (Join-Path $legacy 'shadow-local-ai-install.json') -PathType Leaf)){
                        throw 'The copy source has no valid package identity. No files were changed.'
                    }
                    $collisions=@(Get-ChildItem -LiteralPath $legacy -Force -ErrorAction Stop|Where-Object {
                        $_.Name -ne 'provisioning.lock' -and (Test-Path -LiteralPath (Join-Path $target $_.Name))
                    }|Select-Object -ExpandProperty Name)
                    if($collisions.Count){
                        Write-Host "Cannot copy: the destination already contains $($collisions -join ', '). No files were changed or merged. Select option 1 or 2."
                        continue
                    }
                    return [pscustomobject]@{Root=$target;CopyFrom=$legacy}
                }
                default {throw 'Selection cancelled. No installation or copy performed.'}
            }
        }
    }
    return [pscustomobject]@{Root=$target;CopyFrom=$source}
}

function Confirm-BootstrapInstallation {
    param([Parameter(Mandatory)]$Selection,[string]$ResolvedModelMode='Dual')
    Write-Host "`nInstallation root: $($Selection.Root)"
    Write-Host 'Contains: managed environment, private Kilo CLI, VS Code profile, extensions, runtime state and reports.'
    Write-Host 'Missing tools will be installed. Approved newer tool versions and registered LoKiEnte workspaces will be updated.'
    Write-Host "Model mode: $ResolvedModelMode. Dependency policy file: $(Join-Path $Selection.Root 'update-policy.json')."
    Write-Host 'Global application settings and the model directory configured in LM Studio remain unchanged.'
    Write-Host 'Applications/installers may store their own data and caches outside the installation root.'
    if($Selection.CopyFrom){
        Write-Host "Copy source: $($Selection.CopyFrom)"
        Write-Host 'Close the managed VS Code environment, router and tasks first. The source is retained as a backup.'
        Write-Host 'Afterwards, start only the new environment, never the source and copy in parallel. External models are not moved.'
    }
    return ((Read-Host 'Type exactly y to confirm; any other input cancels without changes') -ceq 'y')
}

function Convert-BootstrapManagedPaths {
    param($Value,[string]$SourceRoot,[string]$TargetRoot)
    if($Value -is [string]){
        $path=$Value.Replace('/','\')
        if($path -ieq $SourceRoot){return $TargetRoot}
        if($path.StartsWith($SourceRoot+'\',[StringComparison]::OrdinalIgnoreCase)){return $TargetRoot.TrimEnd('\','/')+$path.Substring($SourceRoot.Length)}
        return $Value
    }
    if($Value -is [array]){
        return ,@(foreach($item in $Value){Convert-BootstrapManagedPaths $item $SourceRoot $TargetRoot})
    }
    if($Value -is [pscustomobject]){
        foreach($property in $Value.PSObject.Properties){$property.Value=Convert-BootstrapManagedPaths $property.Value $SourceRoot $TargetRoot}
    }
    return $Value
}

function Move-BootstrapCopyEntry {
    param([string]$Source,[string]$Destination)
    if((Get-Item -LiteralPath $Source -Force).PSIsContainer){[IO.Directory]::Move($Source,$Destination)}
    else{[IO.File]::Move($Source,$Destination)}
}

function Copy-BootstrapInstallation {
    param([Parameter(Mandatory)][string]$SourceRoot,[Parameter(Mandatory)][string]$TargetRoot)
    $source=[IO.Path]::GetFullPath($SourceRoot).TrimEnd('\','/')
    $target=[IO.Path]::GetFullPath($TargetRoot)
    if($target -ne [IO.Path]::GetPathRoot($target)){$target=$target.TrimEnd('\','/')}
    if($source -ieq $target.TrimEnd('\','/') -or $target.StartsWith($source+'\',[StringComparison]::OrdinalIgnoreCase) -or
       $source.StartsWith($target.TrimEnd('\','/')+'\',[StringComparison]::OrdinalIgnoreCase)){
        throw 'Source and destination must be different and must not be nested.'
    }
    Assert-BootstrapInstallRoot -Root $source
    if(-not(Test-Path -LiteralPath (Join-Path $source 'shadow-local-ai-install.json') -PathType Leaf)){
        throw 'The copy source has no valid package identity.'
    }
    Assert-BootstrapNoReparsePoint -Path $target
    $processPattern=[regex]::Escape($source)+'(?:[\\\s"'']|$)'
    $active=@(Get-CimInstance Win32_Process -ErrorAction Stop|Where-Object {
        $_.ProcessId -ne $PID -and $_.CommandLine -and $_.CommandLine.Replace('/','\') -match $processPattern
    })
    if($active.Count){throw "Processes are still using the source (PID: $($active.ProcessId -join ', ')). Close managed apps/router/tasks and retry."}
    $locks=New-Object 'Collections.Generic.List[IDisposable]'
    $stage=$null
    $published=New-Object 'Collections.Generic.List[string]'
    $committed=$false
    try{
        $lockNames=@('provisioning.lock','setup-active.lock','runtime\model-pool.lock')
        foreach($name in $lockNames){
            $path=Join-Path $source $name
            Assert-BootstrapNoReparsePoint -Path $path
            if(Test-Path -LiteralPath $path){
                try{$locks.Add([IO.File]::Open($path,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::None))}
                catch [IO.IOException]{throw "Source is locked or unreadable: $name. Allow active setup/model switches to finish."}
            }
        }
        $sourceModified=(Get-Item -LiteralPath $source -Force).LastWriteTimeUtc
        $items=New-Object 'Collections.Generic.List[object]'
        $directories=New-Object 'Collections.Generic.Queue[string]'
        $directories.Enqueue($source)
        while($directories.Count){
            foreach($item in Get-ChildItem -LiteralPath $directories.Dequeue() -Force -ErrorAction Stop){
                # NTFS directory listings can contain stale metadata for hardlinks.
                $item.Refresh()
                if(-not $item.Exists){throw "Copy source is no longer available: $($item.FullName)."}
                if($item.Attributes -band [IO.FileAttributes]::ReparsePoint){throw "Link in copy source: $($item.FullName). Automatic copying is disabled."}
                $relative=$item.FullName.Substring($source.Length+1)
                if($relative -in $lockNames){continue}
                if($item.PSIsContainer){$directories.Enqueue($item.FullName)}
                $items.Add([pscustomobject]@{Relative=$relative;Directory=$item.PSIsContainer;Length=$(if($item.PSIsContainer){0}else{$item.Length});Modified=$item.LastWriteTimeUtc})
            }
        }
        $top=@($items|Where-Object {$_.Relative -notmatch '\\'})
        foreach($item in $top){
            if(Test-Path -LiteralPath (Join-Path $target $item.Relative)){throw "Copy destination already contains $($item.Relative). No files will be merged or overwritten."}
        }
        $stage=Join-Path $target ('.shadow-copy-'+[guid]::NewGuid().ToString('N'))
        [void][IO.Directory]::CreateDirectory($stage)
        foreach($item in $items){
            $destination=Join-Path $stage $item.Relative
            if($item.Directory){[void][IO.Directory]::CreateDirectory($destination);continue}
            $origin=Join-Path $source $item.Relative
            Assert-BootstrapNoReparsePoint -Path $origin
            [IO.File]::Copy($origin,$destination,$false)
        }
        foreach($item in $items){
            $current=Get-Item -LiteralPath (Join-Path $source $item.Relative) -Force
            $current.Refresh()
            if($current.PSIsContainer -ne $item.Directory){throw "Entry type changed in the copy source: $($current.FullName)."}
            if(((-not $item.Directory) -and $current.Length -ne $item.Length) -or $current.LastWriteTimeUtc -ne $item.Modified){
                $sizeInfo=if($item.Directory){''}else{" Size before/after: $($item.Length)/$($current.Length) Bytes."}
                throw "Source changed during copying: $($current.FullName). Modification time UTC before/after: $($item.Modified.ToString('o'))/$($current.LastWriteTimeUtc.ToString('o')).$sizeInfo Close managed applications and retry."
            }
        }
        if((Get-Item -LiteralPath $source -Force).LastWriteTimeUtc -ne $sourceModified){throw "Source root changed during copying: $source. Close managed applications and retry."}
        # Rebase only package-managed configuration, never application databases,
        # LM Studio settings, model ownership or historical logs/backups.
        $jsonFiles=@('toolchain.json','workspaces.json','kilo-managed\kilo.json')
        $workspaceDirectory=Join-Path $stage 'workspaces'
        if(Test-Path -LiteralPath $workspaceDirectory){
            $jsonFiles+=@(Get-ChildItem -LiteralPath $workspaceDirectory -Filter '*.code-workspace' -File|ForEach-Object {'workspaces\'+$_.Name})
        }
        foreach($relative in $jsonFiles){
            $path=Join-Path $stage $relative
            if(-not(Test-Path -LiteralPath $path)){continue}
            try{
                $value=(ConvertFrom-Json -InputObject ('{"value":'+[IO.File]::ReadAllText($path)+'}')).value
                if(($relative -eq 'workspaces.json' -and $value -isnot [array]) -or
                   ($relative -ne 'workspaces.json' -and $value -isnot [pscustomobject])){throw 'Invalid JSON structure'}
                $value=Convert-BootstrapManagedPaths $value $source $target
                $json=ConvertTo-Json -InputObject $value -Depth 100
            }catch{throw "Cannot migrate managed configuration: $relative. Source remains unchanged."}
            [IO.File]::WriteAllText($path,$json,(New-Object Text.UTF8Encoding($false)))
        }
        $oldReport=Join-Path $stage 'provisioning-report.json'
        if(Test-Path -LiteralPath $oldReport){
            $reportBackup=Join-Path $stage ('backups\migration\'+[guid]::NewGuid().ToString('N'))
            [void][IO.Directory]::CreateDirectory($reportBackup)
            [IO.File]::Copy($oldReport,(Join-Path $reportBackup 'provisioning-report.json'),$false)
        }
        $report=[ordered]@{schema=1;status='INCOMPLETE';installRoot=$target;copiedFrom=$source;error='Installation copied; provisioning at the new location must still complete successfully.'}
        [IO.File]::WriteAllText((Join-Path $stage 'provisioning-report.json'),($report|ConvertTo-Json),(New-Object Text.UTF8Encoding($false)))
        # Publish whole top-level entries, with the identity marker last.
        $top=@(Get-ChildItem -LiteralPath $stage -Force|Sort-Object @{Expression={$_.Name -eq 'shadow-local-ai-install.json'}},Name)
        foreach($item in $top){
            $destination=Join-Path $target $item.Name
            if(Test-Path -LiteralPath $destination){throw "Destination was occupied during copying: $($item.Name)."}
            Assert-BootstrapNoReparsePoint -Path $destination
            Move-BootstrapCopyEntry -Source $item.FullName -Destination $destination
            $published.Add($item.Name)
        }
        $committed=$true
    }finally{
        try{
            if(-not $committed){
                for($i=$published.Count-1;$i -ge 0;$i--){
                    Move-BootstrapCopyEntry -Source (Join-Path $target $published[$i]) -Destination (Join-Path $stage $published[$i])
                }
            }
            if($stage -and (Test-Path -LiteralPath $stage)){Remove-Item -LiteralPath $stage -Recurse -Force -ErrorAction Stop}
        }finally{foreach($lock in $locks){$lock.Dispose()}}
    }
}

function Assert-BootstrapNoReparsePoint {
    param([Parameter(Mandatory)][string]$Path)
    $current=[IO.Path]::GetFullPath($Path)
    while($current) {
        $attributes=$null
        try{$attributes=[IO.File]::GetAttributes($current)}
        catch [IO.FileNotFoundException]{}
        catch [IO.DirectoryNotFoundException]{}
        if($null -ne $attributes -and ($attributes -band [IO.FileAttributes]::ReparsePoint)) {
            throw "Reparse point/link in installation path: $current. Use a direct directory; destination remains unchanged."
        }
        $parent=[IO.Directory]::GetParent($current)
        if($null -eq $parent){break}
        $current=$parent.FullName
    }
}

function Get-BootstrapPayloadBytes {
    $bytes=[Convert]::FromBase64String($payloadBase64)
    $sha=[Security.Cryptography.SHA256]::Create()
    try{$actual=([BitConverter]::ToString($sha.ComputeHash($bytes))).Replace('-','').ToLowerInvariant()}finally{$sha.Dispose()}
    if($actual -cne $payloadSha256){throw 'The embedded installation package is corrupt (SHA256).'}
    return ,$bytes
}

function Install-BootstrapPayload {
    param([string]$Root)
    $bytes=Get-BootstrapPayloadBytes
    Add-Type -AssemblyName System.IO.Compression
    $memory=New-Object IO.MemoryStream(,$bytes)
    $archive=New-Object IO.Compression.ZipArchive($memory,[IO.Compression.ZipArchiveMode]::Read,$false)
    $Root=[IO.Path]::GetFullPath($Root)
    $app=[IO.Path]::GetFullPath((Join-Path $Root 'app'))
    $prefix=$app.TrimEnd('\','/')+[IO.Path]::DirectorySeparatorChar
    $transaction=[DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffffffZ')+'-'+[guid]::NewGuid().ToString('N').Substring(0,8)
    $backupRoot=Join-Path $Root ('backups/app/'+$transaction)
    $planned=New-Object 'Collections.Generic.List[object]'
    $destinations=@{}
    try {
        # Check every destination and every existing ancestor before creating
        # directories or replacing files. Textual ZIP-prefix checks alone do
        # not protect against existing directory junctions/symbolic links.
        Assert-BootstrapNoReparsePoint -Path $app
        Assert-BootstrapNoReparsePoint -Path $backupRoot
        foreach($entry in $archive.Entries){
            $normalized=$entry.FullName.Replace('\','/')
            $isDirectory=$normalized.EndsWith('/')
            if($isDirectory){$normalized=$normalized.TrimEnd('/')}
            if([string]::IsNullOrEmpty($normalized) -or $normalized.StartsWith('/')){throw 'Invalid path in embedded package.'}
            $parts=$normalized.Split('/')
            foreach($part in $parts){
                if([string]::IsNullOrEmpty($part) -or $part -in @('.','..') -or
                   $part -match '[<>:"|?*\x00-\x1F]' -or $part.EndsWith('.') -or $part.EndsWith(' ') -or
                   $part -match '^(CON|PRN|AUX|NUL|COM[1-9]|LPT[1-9])(\.|$)'){
                    throw 'Invalid Windows path in embedded package.'
                }
            }
            $relative=$normalized.Replace('/',[IO.Path]::DirectorySeparatorChar)
            $target=[IO.Path]::GetFullPath((Join-Path $app $relative))
            if(-not $target.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){throw 'Invalid path in embedded package.'}
            if($destinations.ContainsKey($target)){throw 'Duplicate destination path in embedded package.'}
            $destinations[$target]=$isDirectory
            $backup=Join-Path $backupRoot $relative
            Assert-BootstrapNoReparsePoint -Path $target
            Assert-BootstrapNoReparsePoint -Path $backup
            if(Test-Path -LiteralPath $target){
                if($isDirectory -and -not(Test-Path -LiteralPath $target -PathType Container)){throw 'Package directory conflicts with an existing file.'}
                if(-not $isDirectory -and -not(Test-Path -LiteralPath $target -PathType Leaf)){throw 'Package file conflicts with an existing directory.'}
            }
            $newBytes=$null
            if(-not $isDirectory){
                $stream=$entry.Open();$copy=New-Object IO.MemoryStream
                try{$stream.CopyTo($copy);$newBytes=$copy.ToArray()}finally{$stream.Dispose();$copy.Dispose()}
            }
            $planned.Add([pscustomobject]@{Target=$target;Relative=$relative;Backup=$backup;IsDirectory=$isDirectory;Bytes=$newBytes})
        }
        foreach($item in $planned){
            $parent=[IO.Directory]::GetParent($item.Target)
            while($parent -and $parent.FullName.StartsWith($prefix,[StringComparison]::OrdinalIgnoreCase)){
                if($destinations.ContainsKey($parent.FullName) -and -not $destinations[$parent.FullName]){throw 'File/directory conflict in the embedded package.'}
                if((Test-Path -LiteralPath $parent.FullName) -and -not(Test-Path -LiteralPath $parent.FullName -PathType Container)){throw 'Package path conflicts with an existing file.'}
                $parent=$parent.Parent
            }
        }
        # Preflight complete. Recheck before each write to catch ordinary
        # concurrent directory changes as well; no global files are replaced.
        foreach($item in $planned){
            $target=$item.Target;$newBytes=$item.Bytes;$backup=$item.Backup
            Assert-BootstrapNoReparsePoint -Path $target
            Assert-BootstrapNoReparsePoint -Path $backup
            if($item.IsDirectory){[void][IO.Directory]::CreateDirectory($target);continue}
            [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($target))
            if(Test-Path -LiteralPath $target){
                $old=[IO.File]::ReadAllBytes($target)
                if([Convert]::ToBase64String($old) -ceq [Convert]::ToBase64String($newBytes)){continue}
                [void][IO.Directory]::CreateDirectory([IO.Path]::GetDirectoryName($backup))
                [IO.File]::Copy($target,$backup,$false)
            }
            $temporary=$target+'.'+[guid]::NewGuid().ToString('N')+'.tmp'
            try{[IO.File]::WriteAllBytes($temporary,$newBytes);Move-Item -LiteralPath $temporary -Destination $target -Force}
            finally{if(Test-Path -LiteralPath $temporary){Remove-Item -LiteralPath $temporary -Force}}
        }
    } finally{$archive.Dispose();$memory.Dispose()}
}

$setupLock=$null
$removeUnclaimedLock=$false
try {
    $InstallRoot=$ExecutionContext.SessionState.Path.GetUnresolvedProviderPathFromPSPath($InstallRoot)
    if($AuditOnly){
        $audit=Read-BootstrapInventory
        $audit|ConvertTo-Json -Depth 15
        exit $audit.exitCode
    }
    if($env:OS -ne 'Windows_NT'){throw 'Run this script on Windows, not on Linux/macOS.'}
    if(-not [Environment]::Is64BitOperatingSystem -or $env:PROCESSOR_ARCHITECTURE -eq 'ARM64' -or $env:PROCESSOR_ARCHITEW6432 -eq 'ARM64'){throw 'Windows x64 is required.'}
    if(-not [Environment]::Is64BitProcess){throw 'Please start the 64-bit version of Windows PowerShell.'}
    $null=Get-BootstrapPayloadBytes
    $selection=Select-BootstrapInstallation -RequestedRoot $InstallRoot -LegacyRoot (Join-Path $env:LOCALAPPDATA 'ShadowLocalAI')
    $InstallRoot=$selection.Root
    $optionsRoot=if($selection.CopyFrom){$selection.CopyFrom}else{$InstallRoot}
    $previousOptions=Read-BootstrapOptionState -Root $optionsRoot
    if(-not $PSBoundParameters.ContainsKey('ModelMode') -or $previousOptions['ModelMode'] -eq $ModelMode){
        foreach($name in $previousOptions.Keys){
            if($PSBoundParameters.ContainsKey($name) -or
               ($name -eq 'ModelKey' -and $PSBoundParameters.ContainsKey('PreferredModel')) -or
               ($name -eq 'PreferredModel' -and $PSBoundParameters.ContainsKey('ModelKey'))){continue}
            Set-Variable -Name $name -Value $previousOptions[$name]
        }
    }
    Assert-BootstrapOptions
    if(-not(Confirm-BootstrapInstallation -Selection $selection -ResolvedModelMode $ModelMode)){
        Write-Host 'Cancelled. No installation or copy performed.'
        exit 0
    }
    $modelChoice=Select-BootstrapModelAction -Root $optionsRoot -Requested $ModelAction -Previous $previousOptions -Arguments $PSBoundParameters -Copying:([bool]$selection.CopyFrom)
    $ModelAction=$modelChoice.Action
    if ($ModelAction -eq 'Keep') {$IndexingMode=$modelChoice.IndexingMode}
    elseif(-not $PSBoundParameters.ContainsKey('IndexingMode')){$IndexingMode=Select-BootstrapIndexingMode -ResolvedModelMode $ModelMode}
    Write-Host "Model maintenance for this run: $ModelAction"
    Assert-BootstrapOptions
    Write-Host "Selected indexing mode: $IndexingMode"
    # Reject redirected installation/backup trees before even creating the
    # package marker or installing a prerequisite.
    Assert-BootstrapInstallRoot -AllowSharedDirectory
    $marker=Join-Path $InstallRoot 'shadow-local-ai-install.json'
    [void][IO.Directory]::CreateDirectory($InstallRoot)
    $lockPath=Join-Path $InstallRoot 'provisioning.lock'
    Assert-BootstrapNoReparsePoint -Path $lockPath
    $removeUnclaimedLock=-not(Test-Path -LiteralPath $marker)
    $lockMode=if($removeUnclaimedLock){[IO.FileMode]::CreateNew}else{[IO.FileMode]::OpenOrCreate}
    try{$setupLock=[IO.File]::Open($lockPath,$lockMode,[IO.FileAccess]::ReadWrite,[IO.FileShare]::None)}
    catch [IO.IOException]{throw 'Installation lock unavailable (concurrent run or file error). No package files replaced.'}
    $script:bootstrapCanWriteReport=$true
    $script:bootstrapStages+=@(@{id='install-root-validated-and-locked';utc=[DateTime]::UtcNow.ToString('o');root=$InstallRoot;status='COMPLETED'})
    $childLockPath=Join-Path $InstallRoot 'setup-active.lock'
    Assert-BootstrapNoReparsePoint -Path $childLockPath
    if(Test-Path -LiteralPath $childLockPath -PathType Leaf){
        try{$childProbe=[IO.File]::Open($childLockPath,[IO.FileMode]::Open,[IO.FileAccess]::Read,[IO.FileShare]::None);$childProbe.Dispose()}
        catch [IO.IOException]{throw 'A previous setup instance is still running. Wait for it to finish before retrying; no package files replaced.'}
    }
    if($selection.CopyFrom){Copy-BootstrapInstallation -SourceRoot $selection.CopyFrom -TargetRoot $InstallRoot}
    if(-not(Test-Path -LiteralPath $marker)){
        $identity=@{schema=1;product='ShadowLocalAI';createdUtc=[DateTime]::UtcNow.ToString('o');bundleVersion=$bundleVersion}|ConvertTo-Json
        [IO.File]::WriteAllText($marker,$identity,(New-Object Text.UTF8Encoding($false)))
    }
    $winget=Find-BootstrapExecutable 'winget.exe' @((Join-Path $env:LOCALAPPDATA 'Microsoft/WindowsApps/winget.exe'))
    if(-not $winget){throw 'WinGet not found. Install/update Microsoft App Installer from the Microsoft Store, then retry.'}
    Install-BootstrapPayload -Root $InstallRoot
    $script:bootstrapStages+=@(@{id='embedded-payload-installed';utc=[DateTime]::UtcNow.ToString('o');bundleVersion=$bundleVersion;payloadSha256=$payloadSha256;status='COMPLETED'})
    . (Join-Path $InstallRoot 'app/DependencyVersions.ps1')
    . (Join-Path $InstallRoot 'app/UpdatePolicy.ps1')
    $UpdatePolicy=Set-LoKiEnteUpdatePolicy -Root $InstallRoot -Requested $UpdatePolicy
    Write-Host "Dependency update policy: $UpdatePolicy (minimum age: 48 hours)"
    $accepted=Resolve-LoKiEnteDependencyPlan -Policy $UpdatePolicy
    $pwsh=Find-BootstrapExecutable 'pwsh.exe' @((Join-Path $env:ProgramFiles 'PowerShell/7/pwsh.exe'),(Join-Path $env:LOCALAPPDATA 'Microsoft/WindowsApps/pwsh.exe'))
    $minimum=if($accepted.powerShell){$accepted.powerShell}else{'7.4.0'}
    $probeVersion='if (([version]::new($PSVersionTable.PSVersion.Major,$PSVersionTable.PSVersion.Minor,$PSVersionTable.PSVersion.Patch,0)) -lt [version]'''+$minimum+''') { exit 3 }; exit 0'
    $current=if($pwsh){Invoke-BootstrapProcess $pwsh @('-NoLogo','-NoProfile','-NonInteractive','-Command',$probeVersion) -TimeoutSeconds 60}else{3}
    if($current -ne 0 -and $current -ne 3){throw 'Could not verify the installed PowerShell 7.'}
    if(-not $pwsh -or ($accepted.powerShell -and $current -eq 3)){
        $action=if($pwsh){'upgrade'}else{'install'}
        Write-Host "WinGet $action for PowerShell 7 ..."
        $arguments=@($action,'--id','Microsoft.PowerShell','--exact','--source','winget','--silent','--accept-package-agreements','--accept-source-agreements','--disable-interactivity')
        if($action -ceq 'install'){$arguments+=@('--no-upgrade')}
        if($accepted.powerShell){$arguments+=@('--version',$accepted.powerShell)}
        $result=Invoke-BootstrapProcess $winget $arguments
        if($result -notin @(0,3010,1641)){throw "PowerShell installation returned exit code $result. Setup will not continue."}
        $env:Path=$env:Path+';'+[Environment]::GetEnvironmentVariable('Path','Machine')+';'+[Environment]::GetEnvironmentVariable('Path','User')
        $pwsh=Find-BootstrapExecutable 'pwsh.exe' @((Join-Path $env:ProgramFiles 'PowerShell/7/pwsh.exe'),(Join-Path $env:LOCALAPPDATA 'Microsoft/WindowsApps/pwsh.exe'))
        if(-not $pwsh){throw 'PowerShell 7 cannot be found yet. Open a new terminal and rerun provisioning.'}
    }
    $versionCheck=Invoke-BootstrapProcess $pwsh @('-NoLogo','-NoProfile','-NonInteractive','-Command',$probeVersion) -TimeoutSeconds 60
    if($versionCheck -ne 0){throw "PowerShell 7 does not meet the required version $minimum. Check the approved version or executable path."}
    $request=[ordered]@{
        ModelMode=$ModelMode;IncludeFastModel=[bool]$IncludeFastModel;AllowPartialGpuOffload=[bool]$AllowPartialGpuOffload;AllowUnfitAttempt=[bool]$AllowUnfitAttempt;RouterPort=$RouterPort
        ModelAction=$ModelAction;UpdatePolicy=$UpdatePolicy;DependencyPlan=$accepted
        IndexingMode=$IndexingMode;BundleVersion=$bundleVersion;PayloadSha256=$payloadSha256
        InstallRoot=$InstallRoot;PreferredModel=$PreferredModel;ModelKey=$ModelKey
        ApiTokenEnvironmentVariable=$ApiTokenEnvironmentVariable;ContextLength=$ContextLength;Port=$Port
        ProjectPath=@($ProjectPath);SkipModelDownload=[bool]$SkipModelDownload
        UpdateManaged=[bool]$UpdateManaged;NoShortcut=[bool]$NoShortcut
        RunAcceptanceTest=[bool]$RunAcceptanceTest;SkipAcceptanceTest=[bool]$SkipAcceptanceTest
        BootstrapEvidence=@{startedUtc=$script:bootstrapStartedUtc;handoffUtc=[DateTime]::UtcNow.ToString('o');source=$PSCommandPath;powerShell=$PSVersionTable.PSVersion.ToString();os=[Environment]::OSVersion.VersionString;is64BitProcess=[Environment]::Is64BitProcess;bundleVersion=$bundleVersion;payloadSha256=$payloadSha256;payloadVerified=$true;payloadInstalled=$true;updatePolicy=$UpdatePolicy;acceptedDependencies=$accepted;commands=$script:bootstrapCommands;stages=$script:bootstrapStages}
    }
    $requestPath=Join-Path $InstallRoot ('setup-request-'+[guid]::NewGuid().ToString('N')+'.json')
    try {
        [IO.File]::WriteAllText($requestPath,($request|ConvertTo-Json -Depth 10),(New-Object Text.UTF8Encoding($false)))
        $entry=Join-Path $InstallRoot 'app/Invoke-SetupRequest.ps1'
        $result=Invoke-BootstrapProcess $pwsh @('-NoLogo','-NoProfile','-ExecutionPolicy','Bypass','-File',$entry,'-RequestPath',$requestPath) -TimeoutSeconds 0
    } finally {if(Test-Path -LiteralPath $requestPath){Remove-Item -LiteralPath $requestPath -Force}}
    exit $result
} catch {
    if($AuditOnly){
        [pscustomobject]@{schema=2;mode='AUDIT_ONLY';status='BLOCKED';exitCode=2;provisioningPerformed=$false;inferenceVerified=$false;error=$_.Exception.Message}|ConvertTo-Json -Depth 5
        exit 2
    }
    if($script:bootstrapCanWriteReport){
        try{
            $failurePath=Join-Path $InstallRoot 'bootstrap-failure.json'
            $failureReport=@{schema=2;status='INCOMPLETE';phase='bootstrap';startedUtc=$script:bootstrapStartedUtc;finishedUtc=[DateTime]::UtcNow.ToString('o');installRoot=$InstallRoot;bundleVersion=$bundleVersion;payloadSha256=$payloadSha256;powerShell=$PSVersionTable.PSVersion.ToString();os=[Environment]::OSVersion.VersionString;error=$_.Exception.Message;line=$_.InvocationInfo.ScriptLineNumber;stack=$_.ScriptStackTrace;commands=$script:bootstrapCommands;stages=$script:bootstrapStages}
            [IO.File]::WriteAllText($failurePath,($failureReport|ConvertTo-Json -Depth 15),(New-Object Text.UTF8Encoding($false)))
            $mainReport=Join-Path $InstallRoot 'provisioning-report.json'
            Assert-BootstrapNoReparsePoint -Path $mainReport
            if(Test-Path -LiteralPath $mainReport){
                $backupDirectory=Join-Path $InstallRoot 'backups/reports';[void][IO.Directory]::CreateDirectory($backupDirectory)
                $backup=Join-Path $backupDirectory ([DateTime]::UtcNow.ToString('yyyyMMddTHHmmssfffffffZ')+'-before-bootstrap-failure.json')
                [IO.File]::Copy($mainReport,$backup)
                $failureReport.previousReportBackup=$backup
            }
            [IO.File]::WriteAllText($mainReport,($failureReport|ConvertTo-Json -Depth 15),(New-Object Text.UTF8Encoding($false)))
        }catch{Write-Warning 'Could not save bootstrap failure diagnostics.'}
    }
    Write-Error -Message $_.Exception.Message -ErrorAction Continue
    exit 1
}finally{
    if($null -ne $setupLock){
        $setupLock.Dispose()
        if($removeUnclaimedLock -and -not(Test-Path -LiteralPath $marker)){Remove-Item -LiteralPath $lockPath -Force}
    }
}
